DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['riders','trip_requests','vehicles','dispatch_assignments','outbox_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY organization_isolation ON %I USING (organization_id=current_setting(''app.organization_id'',true)::uuid) WITH CHECK (organization_id=current_setting(''app.organization_id'',true)::uuid)',t);END LOOP;END $$;
